&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Base salary range for this role is&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;$160,000 - $245,000&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;+ equity in the company&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Salary will be based on several factors including, but not limited&amp;nbsp;to:&amp;nbsp;knowledge and skills, education, and experience level&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Comprehensive benefits package including paid time off, medical/dental/vision coverage, life insurance, paid parental leave, and many other&amp;nbsp;perks&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
