&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Bachelor’s degree in electrical, electronics, mechanical, aerospace, or other relevant engineering discipline&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;10+ years of experience in a&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;high volume, rapid production environment in a&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;manufacturing, integration, and/or design engineering role&amp;nbsp;with&amp;nbsp;demonstrated&amp;nbsp;excellence leading product development and process improvements.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Strong understanding of IPC standards (e.g., IPC-A-610, IPC-A-600, J-STD-001) for PCB/PCBA workmanship and inspection&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
