&lt;ul&gt;
&lt;li&gt;&lt;span class=&quot;TextRun SCXW98052880 BCX0&quot; lang=&quot;EN&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW98052880 BCX0&quot;&gt;Serve as Responsible Engineer for&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW98052880 BCX0&quot;&gt;A&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW98052880 BCX0&quot;&gt;vionics&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW98052880 BCX0&quot;&gt;s&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW98052880 BCX0&quot;&gt;ystem design, performance, and hardware across the computing, power system, instrumentation,&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW98052880 BCX0&quot;&gt;RF components,&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW98052880 BCX0&quot;&gt;GNC sensors, and harnessing on the satellite bus&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW98052880 BCX0&quot; data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
