&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Define EMI/EMC test and compliance philosophy&amp;nbsp;for K2 Avionics.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:780,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;Lead design of&amp;nbsp;K2&amp;nbsp;EMC&amp;nbsp;test infrastructure,&amp;nbsp;developing the hardware and&amp;nbsp;software to&amp;nbsp;enable high-rate EMC&amp;nbsp;development and production testing.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:780,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Work&amp;nbsp;alongside&amp;nbsp;electrical&amp;nbsp;engineers&amp;nbsp;and mechanical engineers&amp;nbsp;to&amp;nbsp;test for&amp;nbsp;and correct EMI-susceptible&amp;nbsp;and high emissions&amp;nbsp;electrical designs.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:780,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
