&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Strong experience in developing filter topologies including FIR filters, IIR filters, and trading between both implementations&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
