&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Strong debugging skills across silicon, package, PCB, firmware, and system boundaries.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Ability to work closely with SerDes IP/design, SI, package, board, firmware, and digital teams.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
