&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Internship or research experience with solar arrays or power systems for space applications&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:240,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
