&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Assemble precision&amp;nbsp;turbopumps and fluid loop mechanisms&amp;nbsp;(rotating&amp;nbsp;assemblies, bearings,&amp;nbsp;seals,&amp;nbsp;valves,&amp;nbsp;accumulators)&amp;nbsp;hardware&amp;nbsp;to&amp;nbsp;engineering drawings, BOMs, and work instructions&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Build,&amp;nbsp;operate, and&amp;nbsp;maintain&amp;nbsp;development flow loops and test stands, including plumbing,&amp;nbsp;instrumentation, and dataacquisition&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Install and&amp;nbsp;check&amp;nbsp;out&amp;nbsp;pressure transducers,&amp;nbsp;temperature sensors, and flow meters&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
