&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience working in the US national security community as a service member, civil servant, or contractor&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
